questionvariables.text:
/* Define the data*/ 
XX:makelist(rand(20),i,1,7); /*Number of absences*/
YY:makelist(rand(100),i,1,7); /*Final grade */
xy:XX * YY;
x_sq:XX^2;
y_sq:YY^2;
/* Calculate the number of data points (n) */ 
n: length(XX);  
/* Calculate the sums of X and Y */ 
sumX: sum(XX[i], i, 1, n); 
sumY: sum(YY[i], i, 1, n);  
/* Calculate the sum of the products of X and Y */ 
sumXY: sum(XX[i] * YY[i], i, 1, n);  
/* Calculate the sum of the squares of X and Y */ 
sumX2: sum(XX[i]^2, i, 1, n); 
sumY2: sum(YY[i]^2, i, 1, n);  

/* Given data */ 
n: n; 
sum_x: sumX; 
sum_y: sumY; 
sum_xy: sumXY; 
sum_x2: sumX2;  
/* Calculate the slope (b) */ 
b: (n * sum_xy - sum_x * sum_y) / (n * sum_x2 - sum_x^2);  
/* Calculate the intercept (a) */ 
a: (sum_y - b * sum_x) / n; 
/* Define the regression equation Y on X */ 
Y_on_X: a + b * X;


/* Given data */ 
 sum_y2: sumY2;  
/* Calculate the slope (beta) */ 
beta: (n * sum_xy - sum_x * sum_y) / (n * sum_y2 - sum_y^2);  
/* Calculate the intercept (alpha) */ 
alpha: (sum_x - beta * sum_y) / n;  
/* Define the regression equation X on Y */ 
X_on_Y: alpha + beta * Y; 

/*Model answers*/
ta1:Y_on_X;
alt_ta1: decimalplaces(a,2) + decimalplaces(b,2)*X;
ta2:X_on_Y;
alt_ta2: decimalplaces(alpha,2) + decimalplaces(beta,2)*Y;
